arguments.command:
mkdir -p /tmp/work && cd /tmp/work && cat > p1.py <<'EOF'
import re, sys, unicodedata
path = sys.argv[1]
raw = open(path, encoding='utf-8').read().split('\n')
g = raw[5:111]
W = max(len(l) for l in g)
grid = [l.ljust(W) for l in g]
H = len(grid)

LINECH = set('-~|+/\\._│─')
def is_text(ch):
    return ch != ' ' and ch not in LINECH

# tokens
tokrows = []
for r in range(H):
    row = grid[r]
    toks = []
    c = 0
    while c < W:
        if is_text(row[c]):
            s = c
            while c < W and is_text(row[c]):
                c += 1
            toks.append((s, c, row[s:c]))
        else:
            c += 1
    tokrows.append(toks)

# group tokens on a row into text-lines: join tokens separated by exactly one space
lines = []
for r in range(H):
    cur = None
    for (s,e,t) in tokrows[r]:
        if cur and s == cur[1] + 1:
            cur = (cur[0], e, cur[2] + ' ' + t)
        else:
            if cur: lines.append((r, cur[0], cur[1], cur[2]))
            cur = (s,e,t)
    if cur: lines.append((r, cur[0], cur[1], cur[2]))

print("num text-lines:", len(lines))
from collections import Counter
cc = Counter(l[3] for l in lines)
print("sample lines:", lines[:10])
# group into blocks: same start col, consecutive rows
lines.sort(key=lambda x:(x[1], x[0]))
used = [False]*len(lines)
bykey = {}
for i,(r,s,e,t) in enumerate(lines):
    bykey.setdefault(s, []).append(i)
blocks = []
for s, idxs in bykey.items():
    idxs.sort(key=lambda i: lines[i][0])
    cur = []
    for i in idxs:
        if cur and lines[i][0] == lines[cur[-1]][0] + 1:
            cur.append(i)
        else:
            if cur: blocks.append(cur)
            cur = [i]
    if cur: blocks.append(cur)
print("num blocks:", len(blocks))
hist = Counter(len(b) for b in blocks)
print("block sizes:", hist)
EOF
python3 -I p1.py /app/dataset/genealogy_trees.txt

