cd /tmp/work && cat > boxes.py <<'EOF'
import sys
from collections import Counter, defaultdict
raw = open('/app/dataset/genealogy_trees.txt', encoding='utf-8').read().split('\n')
g = raw[5:111]
W = max(len(l) for l in g)
grid = [l.ljust(W) for l in g]
H = len(grid)
LINECH = set('-~|+/\\._│─')
def is_text(ch): return ch != ' ' and ch not in LINECH

tokrows=[]
for r in range(H):
    row=grid[r]; toks=[]; c=0
    while c<W:
        if is_text(row[c]):
            s=c
            while c<W and is_text(row[c]): c+=1
            toks.append((s,c,row[s:c]))
        else: c+=1
    tokrows.append(toks)

lines=[]
for r in range(H):
    cur=None
    for (s,e,t) in tokrows[r]:
        if cur and s==cur[1]+1: cur=(cur[0],e,cur[2]+' '+t)
        else:
            if cur: lines.append([r,cur[0],cur[1],cur[2]])
            cur=(s,e,t)
    if cur: lines.append([r,cur[0],cur[1],cur[2]])

bykey=defaultdict(list)
for i,(r,s,e,t) in enumerate(lines): bykey[s].append(i)
blocks=[]
for s,idxs in bykey.items():
    idxs.sort(key=lambda i: lines[i][0])
    cur=[]
    for i in idxs:
        if cur and lines[i][0]==lines[cur[-1]][0]+1: cur.append(i)
        else:
            if cur: blocks.append(cur)
            cur=[i]
    if cur: blocks.append(cur)

boxes=[]
for b in blocks:
    rows=[lines[i][0] for i in b]
    txts=[lines[i][3] for i in b]
    s=lines[b[0]][1]
    mw=max(len(t) for t in txts)
    boxes.append(dict(name=' '.join(txts), rows=rows, L=s-2, R=s-2+mw+4-1, txtrows=(rows[0],rows[-1])))
boxes.sort(key=lambda x:(x['rows'][0], x['L']))
print('total boxes', len(boxes))
# distribution of text first-row
print(sorted(Counter(b['rows'][0] for b in boxes).items()))
for b in boxes[:15]: print(b['rows'], b['L'], b['R'], repr(b['name']))
