from collections import Counter, defaultdict
raw = open('/app/dataset/genealogy_trees.txt', encoding='utf-8').read().split('\n')
g = raw[5:111]
W = max(len(l) for l in g); grid=[l.ljust(W) for l in g]; H=len(grid)
LINECH=set('-~|+/\\._│─')
def is_text(ch): return ch!=' ' and ch not in LINECH
lines=[]
for r in range(H):
    row=grid[r]; toks=[]; c=0
    while c<W:
        if is_text(row[c]):
            s=c
            while c<W and is_text(row[c]): c+=1
            toks.append((s,c,row[s:c]))
        else: c+=1
    cur=None
    for (s,e,t) in toks:
        if cur and s==cur[1]+1: cur=(cur[0],e,cur[2]+' '+t)
        else:
            if cur: lines.append([r,cur[0],cur[1],cur[2]])
            cur=(s,e,t)
    if cur: lines.append([r,cur[0],cur[1],cur[2]])
lines=[l for l in lines if len(l[3])>1]
bykey=defaultdict(list)
for i,l in enumerate(lines): bykey[l[1]].append(i)
blocks=[]
for s,idxs in bykey.items():
    idxs.sort(key=lambda i: lines[i][0]); cur=[]
    for i in idxs:
        if cur and lines[i][0]==lines[cur[-1]][0]+1: cur.append(i)
        else:
            if cur: blocks.append(cur)
            cur=[i]
    if cur: blocks.append(cur)
V=set('|│')
stats=Counter()
samples=[]
for b in blocks:
    txts=[lines[i][3] for i in b]; rs=[lines[i][0] for i in b]
    L=lines[b[0]][1]-2; R=L+max(len(t) for t in txts)+3
    # extent of side chars
    up=rs[0]
    while up-1>=0 and (grid[up-1][L] in V or grid[up-1][R] in V): up-=1
    dn=rs[-1]
    while dn+1<H and (grid[dn+1][L] in V or grid[dn+1][R] in V): dn+=1
    # corners
    topc = [r for r in range(max(0,up-2), up+1) if grid[r][L]=='+' or grid[r][R]=='+']
    botc = [r for r in range(dn, min(H,dn+3)) if grid[r][L]=='+' or grid[r][R]=='+']
    stats[(up-rs[0], dn-rs[-1], bool(topc), bool(botc))]+=1
    samples.append((txts, L,R,rs,up,dn,topc,botc))
for k,v in sorted(stats.items(), key=lambda x:-x[1]): print(k,v)
print(len(blocks))
