import sys; sys.path.insert(0,'/tmp/work')
import lib
from collections import Counter, defaultdict, deque
G=lib.GRID; H=lib.H; W=lib.W; at=lib.at
bs=lib.find_boxes()
BOX=[[-1]*W for _ in range(H)]
for b in bs:
    for r in range(b['rt'], b['rb']+1):
        for c in range(b['L'], b['R']+1): BOX[r][c]=b['id']

WIRE = set('-~|+/\\._│')
def iswire(r,c):
    return 0<=r<H and 0<=c<W and G[r][c] in WIRE and BOX[r][c]<0

VSET=set('|│/\\._')
HSET=set('-~+')

HGAP = int(sys.argv[1]) if len(sys.argv)>1 else 3
VGAP = int(sys.argv[2]) if len(sys.argv)>2 else 2

# union-find over wire cells
par={}
def find(x):
    while par[x]!=x:
        par[x]=par[par[x]]; x=par[x]
    return x
def union(a,b):
    ra,rb=find(a),find(b)
    if ra!=rb: par[ra]=rb

cells=[(r,c) for r in range(H) for c in range(W) if iswire(r,c)]
for x in cells: par[x]=x
cs=set(cells)

for (r,c) in cells:
    ch=G[r][c]
    # horizontal link: only between h-ish chars
    if ch in HSET:
        for d in range(1,HGAP+1):
            if (r,c+d) in cs and G[r][c+d] in HSET:
                union((r,c),(r,c+d)); break
            if 0<=c+d<W and BOX[r][c+d]>=0: break
    # vertical link: vertical chars connect downward, allowing col shift +-1 and row gap
    if ch in VSET or ch=='+':
        done=False
        for d in range(1,VGAP+1):
            for dc in (0,-1,1):
                nr,nc=r+d,c+dc
                if (nr,nc) in cs and (G[nr][nc] in VSET or G[nr][nc]=='+'):
                    union((r,c),(nr,nc)); done=True
            if done: break
comps=defaultdict(list)
for x in cells: comps[find(x)].append(x)
print('num wire components', len(comps))

# attach boxes: a box's bottom-adjacent wire cells, and top-adjacent
def below_cells(b):
    out=[]
    for c in range(b['L'],b['R']+1):
        if iswire(b['rb']+1,c): out.append((b['rb']+1,c))
    return out
def above_cells(b):
    out=[]
    for c in range(b['L'],b['R']+1):
        if iswire(b['rt']-1,c): out.append((b['rt']-1,c))
    return out

comp_children=defaultdict(set); comp_parent=defaultdict(set)
for b in bs:
    for x in below_cells(b): comp_parent[find(x)].add(b['id'])
    for x in above_cells(b): comp_children[find(x)].add(b['id'])

stats=Counter()
for k in set(list(comp_children)+list(comp_parent)):
    stats[(len(comp_parent[k]), len(comp_children[k]))]+=1
print('(nparents, nchildren) per component:')
for k,v in sorted(stats.items(), key=lambda x:-x[1])[:20]: print('   ',k,v)

parent_of=defaultdict(set)
for k in set(list(comp_children)+list(comp_parent)):
    for ch_ in comp_children[k]:
        for p in comp_parent[k]: parent_of[ch_].add(p)
np_=Counter(len(parent_of[b['id']]) for b in bs)
print('parents per box:', np_)
roots=[b['name'] for b in bs if len(parent_of[b['id']])==0]
print('roots:', roots[:10], len(roots))
multi=[(bs[i]['name'], [bs[p]['name'] for p in v]) for i,v in parent_of.items() if len(v)>1]
print('multi-parent:', len(multi))
for m in multi[:10]: print('   ',m)
EOF
