import sys, json; sys.path.insert(0,'/tmp/work')
import lib3 as L
from collections import defaultdict, Counter
G=L.GRID; H=L.H; W=L.W; free=L.free; at=L.at; bs=L.BOXES; HCH=L.HCH
st=json.load(open('stems.json'))
up={int(k):tuple(v) for k,v in st['up'].items()}
down={int(k):tuple(v) for k,v in st['down'].items()}
jrow=defaultdict(list)
for i,v in up.items():
    if v[0]=='bus': jrow[v[1]].append((v[2],'C',i))
for i,v in down.items():
    if v[0]=='bus': jrow[v[1]].append((v[2],'P',i))
def maxgap(r,a,b):
    mx=0; run=0
    for c in range(a+1,b):
        if (free(r,c) and at(r,c) in HCH) or L.BOXAT[r][c]>=0: run=0
        else: run+=1; mx=max(mx,run)
    return mx
TH=3
groups=[]
for r,js in sorted(jrow.items()):
    js.sort(); cur=[js[0]]
    for prev,nxt in zip(js,js[1:]):
        if maxgap(r,prev[0],nxt[0])<=TH: cur.append(nxt)
        else: groups.append((r,cur)); cur=[nxt]
    groups.append((r,cur))
# Test: is parent junction near midpoint of children span?
errs=[]
for r,gp in groups:
    P=[x for x in gp if x[1]=='P']; C=[x for x in gp if x[1]=='C']
    if len(P)==1 and len(C)>=2:
        pc=P[0][0]; lo=min(x[0] for x in C); hi=max(x[0] for x in C)
        mid=(lo+hi)/2
        errs.append((abs(pc-mid), r, pc, lo, hi, len(C)))
errs.sort(reverse=True)
print('parent offset from children-midpoint, top deviations:')
for e in errs[:15]: print('   dev=%.1f row=%d pcol=%d span=(%d,%d) nkids=%d'%e)
print()
print('deviation histogram:', Counter(round(e[0]) for e in errs))
# also: is parent always within [lo,hi]?
inside=sum(1 for e in errs if e[3]<=e[2]<=e[4])
print('parent inside children span:', inside, '/', len(errs))
EOF
