    """True if border row r of `box` is really a connector passing behind it."""
    return any(at(r, box["L"] - d) in HCH or at(r, box["R"] + d) in HCH
               for d in (1, 2, 3))


def trace(r, c, step, box):
    """Walk a vertical stem from (r, c); return ('bus', row, col) or ('box', id)."""
    cur = (r, c)
    for _ in range(300):
        rr, cc = cur
        if free(rr, cc) and at(rr, cc) in HCH:
