            if widest_break(r, prev[0], nxt[0]) <= MAX_GAP:
                run.append(nxt)
            else:
                segments.append((r, run))
                run = [nxt]
        segments.append((r, run))

    parent = {i: v[1] for i, v in up.items() if v[0] == "box"}
    for _r, seg in segments:
        parents = [x for x in seg if x[1] == "P"]
        children = [x for x in seg if x[1] == "C"]
        if len(parents) == 1:
            for ch in children:
                parent[ch[2]] = parents[0][2]
    return parent


def answer() -> int:
    parent = build_tree()
    children = defaultdict(list)
    for c, p in parent.items():
        children[p].append(c)
    name = {b["id"]: b["name"] for b in BOXES}
    id_of = {b["name"]: b["id"] for b in BOXES}

    # Walk up four generations from the target.
    node = id_of[TARGET]
    for _ in range(GENERATIONS_UP):
        node = parent[node]
    ancestor = node

    balance = {}
