            line = line.rstrip("\n")
            if not line:
                continue
            first, last, bal = line.rsplit(",", 2)
            balance[first + " " + last] = int(bal)

    total = 0
    for child in children[ancestor]:
        grandchildren = [g for c in children[child] for g in children[c]]
        if len(grandchildren) > 1:
            total += balance[name[child]]
    return total


