# -*- coding: utf-8 -*-
"""The Heir's Estate.

Parses the ASCII family tree in /app/dataset/genealogy_trees.txt, finds the
great-great-grandparent of 'Dawid Majtyka', and sums the account balances of
that ancestor's direct children who have more than one grandchild.

The diagram is degraded: horizontal connector lines are peppered with '~' and
one-character gaps, vertical stems jog sideways by a column and sometimes use
'/', '\\', '_' or '.' instead of '|'. The parser therefore works structurally:

  1. Locate person boxes from their text, then recover each box's frame.
  2. From each box walk one vertical stem up (to its parent's connector bus)
     and one down (to the bus feeding its children), tolerating jogs and gaps.
  3. Group stem endpoints that land on the same row into connector segments,
     splitting only where the horizontal line is genuinely broken. Each segment
     has one parent stem and the child stems hanging off it.
"""

from collections import defaultdict

TREE_PATH = "/app/dataset/genealogy_trees.txt"
CSV_PATH = "/app/dataset/people_accounts.csv"

TARGET = "Dawid Majtyka"
GENERATIONS_UP = 4  # great-great-grandparent

VCH = set("|│")                 # box side walls
HCH = set("-~+")                     # horizontal connector material
VCHR = set("|│/\\._")           # anything a vertical stem may be drawn with
WIRE = set("-~|+/\\._│")
MAX_GAP = 3                          # widest break that is noise, not a real split


def _load_grid():
    raw = open(TREE_PATH, encoding="utf-8").read().split("\n")
    # Skip the "FAMILY TREE GENERATOR" banner and the trailing rule.
    rows = [l for l in raw]
    start = next(i for i, l in enumerate(rows) if l.startswith("--- FAMILY")) + 1
    end = next(i for i in range(len(rows) - 1, -1, -1) if rows[i].startswith("====="))
    grid = rows[start:end]
    width = max(len(l) for l in grid)
    return [l.ljust(width) for l in grid], len(grid), width


GRID, H, W = _load_grid()


def at(r, c):
    return GRID[r][c] if 0 <= r < H and 0 <= c < W else " "


def is_text(ch):
    return ch != " " and ch not in WIRE


def find_boxes():
    """Recover each person box from its name text plus surrounding frame."""
    # Text runs, joining tokens that are a single space apart ("Dawid Majtyka").
    text_lines = []
    for r in range(H):
        row = GRID[r]
        toks, c = [], 0
        while c < W:
            if is_text(row[c]):
                s = c
                while c < W and is_text(row[c]):
                    c += 1
                toks.append((s, c, row[s:c]))
            else:
                c += 1
        cur = None
        for s, e, t in toks:
            if cur and s == cur[1] + 1:
                cur = (cur[0], e, cur[2] + " " + t)
            else:
                if cur:
                    text_lines.append([r, cur[0], cur[1], cur[2]])
                cur = (s, e, t)
        if cur:
            text_lines.append([r, cur[0], cur[1], cur[2]])
    text_lines = [l for l in text_lines if len(l[3]) > 1]  # drop stray noise glyphs

    # A name may wrap onto a second line; those share a left edge on adjacent rows.
    by_left = defaultdict(list)
    for i, l in enumerate(text_lines):
        by_left[l[1]].append(i)
    blocks = []
    for _, idxs in by_left.items():
        idxs.sort(key=lambda i: text_lines[i][0])
        run = []
        for i in idxs:
            if run and text_lines[i][0] == text_lines[run[-1]][0] + 1:
                run.append(i)
            else:
                if run:
                    blocks.append(run)
                run = [i]
        if run:
            blocks.append(run)

    boxes = []
    for blk in blocks:
        txts = [text_lines[i][3] for i in blk]
        rows = [text_lines[i][0] for i in blk]
        left = text_lines[blk[0]][1] - 2
        right = left + max(len(t) for t in txts) + 3
        # Grow along the side walls to find the top and bottom border rows.
        top = rows[0]
        while top - 1 >= 0 and (at(top - 1, left) in VCH or at(top - 1, right) in VCH):
            top -= 1
        bot = rows[-1]
        while bot + 1 < H and (at(bot + 1, left) in VCH or at(bot + 1, right) in VCH):
            bot += 1
        boxes.append(dict(name=" ".join(txts), L=left, R=right,
                          rt=top - 1, rb=bot + 1, side_top=top, side_bot=bot,
                          trow=rows[0], brow=rows[-1]))
    boxes.sort(key=lambda b: (b["rt"], b["L"]))
    for i, b in enumerate(boxes):
        b["id"] = i
    return boxes


BOXES = find_boxes()

# Mask of cells owned by a box (frame + interior), so connector tracing can tell
# a box edge apart from a connector line that merely passes nearby.
FRAME = [[False] * W for _ in range(H)]
BOX_AT = [[-1] * W for _ in range(H)]
for _b in BOXES:
    _l, _r, _t, _bo = _b["L"], _b["R"], _b["rt"], _b["rb"]
    for _row in range(max(0, _t), min(H, _bo + 1)):
        for _col in (_l, _r):
            if 0 <= _col < W:
                FRAME[_row][_col] = True
                BOX_AT[_row][_col] = _b["id"]
    for _col in range(max(0, _l), min(W, _r + 1)):
        if at(_t, _col) in HCH:
            FRAME[_t][_col] = True
            BOX_AT[_t][_col] = _b["id"]
        if at(_bo, _col) in HCH:
            FRAME[_bo][_col] = True
            BOX_AT[_bo][_col] = _b["id"]
