            return ("bus", rr, cc)
        nxt = None
        for dist in (1, 2, 3):          # tolerate vertical gaps
            cands = []
            for dc in (0, -1, 1):       # tolerate sideways jogs
                nr, nc = rr + step * dist, cc + dc
                if not (0 <= nr < H and 0 <= nc < W):
                    continue
                owner = BOX_AT[nr][nc]
                if owner == box["id"]:
                    # Our own border; only a real bus running behind it counts.
                    if at(nr, nc) in HCH and _is_through_bus(box, nr):
                        return ("bus", nr, nc)
                    continue
                if owner >= 0:
                    return ("box", owner)   # stem lands straight on another box
                if free(nr, nc) and at(nr, nc) in VCHR | HCH:
                    cands.append((0 if at(nr, nc) in VCHR else 1, abs(dc), nr, nc))
            if cands:
                cands.sort()
                nxt = (cands[0][2], cands[0][3])
                break
        if nxt is None:
            return None
        cur = nxt
    return None


def stem_start(box, rows):
    """Pick the stem attachment nearest the box centre among candidate rows."""
    centre = (box["L"] + box["R"]) / 2
    best = None
    for r in rows:
        for c in range(box["L"], box["R"] + 1):
            if free(r, c) and at(r, c) in VCHR:
                if best is None or abs(c - centre) < abs(best[1] - centre):
                    best = (r, c)
    return best


def build_tree():
    up, down = {}, {}
    for b in BOXES:
        s = stem_start(b, range(b["rt"] - 2, b["side_top"] + 1))
        if s:
            res = trace(s[0], s[1], -1, b)
            if res:
                up[b["id"]] = res
        s = stem_start(b, range(b["side_bot"], b["rb"] + 3))
        if s:
            res = trace(s[0], s[1], 1, b)
            if res:
                down[b["id"]] = res

    # Collect stem endpoints per row: 'C' = a child hanging below, 'P' = the parent.
    per_row = defaultdict(list)
    for i, v in up.items():
        if v[0] == "bus":
            per_row[v[1]].append((v[2], "C", i))
    for i, v in down.items():
        if v[0] == "bus":
            per_row[v[1]].append((v[2], "P", i))

    def widest_break(r, a, b):
        worst = run = 0
        for c in range(a + 1, b):
            if (free(r, c) and at(r, c) in HCH) or BOX_AT[r][c] >= 0:
                run = 0
            else:
                run += 1
                worst = max(worst, run)
        return worst

    # Split each row into connector segments at genuine breaks in the line.
    segments = []
    for r, js in sorted(per_row.items()):
        js.sort()
        run = [js[0]]
        for prev, nxt in zip(js, js[1:]):
            if widest_break(r, prev[0], nxt[0]) <= MAX_GAP:
                run.append(nxt)
            else:
                segments.append((r, run))
                run = [nxt]
        segments.append((r, run))

    parent = {i: v[1] for i, v in up.items() if v[0] == "box"}
    for _r, seg in segments:
        parents = [x for x in seg if x[1] == "P"]
        children = [x for x in seg if x[1] == "C"]
        if len(parents) == 1:
            for ch in children:
                parent[ch[2]] = parents[0][2]
    return parent


def answer() -> int:
    parent = build_tree()
    children = defaultdict(list)
    for c, p in parent.items():
        children[p].append(c)
    name = {b["id"]: b["name"] for b in BOXES}
    id_of = {b["name"]: b["id"] for b in BOXES}

    # Walk up four generations from the target.
    node = id_of[TARGET]
    for _ in range(GENERATIONS_UP):
        node = parent[node]
    ancestor = node

    balance = {}
    with open(CSV_PATH, encoding="utf-8") as f:
        next(f)
        for line in f:
            line = line.rstrip("\n")
            if not line:
